     1	package br.com.pousadamarealta.reservas.messaging;
     2	
     3	import java.time.Clock;
     4	import java.time.LocalDate;
     5	import java.util.HashMap;
     6	import java.util.Map;
     7	
     8	/** Limita quantas mensagens um mesmo hóspede (pelo endereço) recebe por dia. */
     9	public final class DailyLimitRule implements MessageRule {
    10	
    11	    private record Key(String address, LocalDate day) {
    12	    }
    13	
    14	    private final Clock clock;
    15	    private final int maxPerDay;
    16	    private final Map<Key, Integer> counts = new HashMap<>();
    17	
    18	    public DailyLimitRule(Clock clock, int maxPerDay) {
    19	        this.clock = clock;
    20	        this.maxPerDay = maxPerDay;
    21	    }
    22	
    23	    @Override
    24	    public synchronized void apply(Draft draft) {
    25	        Key key = new Key(draft.to(), LocalDate.now(clock));
    26	        int sent = counts.getOrDefault(key, 0);
    27	        if (sent >= maxPerDay) {
    28	            draft.block();
    29	            return;
    30	        }
    31	        counts.put(key, sent + 1);
    32	    }
    33	}
