     5	/** Passa a mensagem, na ordem, pelas regras que valem no modo atual. Mensagem bloqueada não segue adiante. */
     6	public final class MessagePipeline {
     7	
     8	    private final List<MessageRule> rules;
     9	
    10	    public MessagePipeline(boolean testMode, List<ScopedRule> scopedRules) {
    11	        this.rules = scopedRules.stream()
    12	                .filter(scoped -> scoped.scope().appliesTo(testMode))
    13	                .map(ScopedRule::rule)
    14	                .toList();
    15	    }
    16	
    17	    public void run(Draft draft) {
    18	        for (MessageRule rule : rules) {
    19	            if (draft.isBlocked()) {
    20	                return;
    21	            }
    22	            rule.apply(draft);
    23	        }
    24	    }
    25	}
