     1	package br.com.pousadamarealta.reservas.messaging;
     2	
     3	import static br.com.pousadamarealta.reservas.messaging.ScopedRule.always;
     4	import static br.com.pousadamarealta.reservas.messaging.ScopedRule.liveOnly;
     5	import static br.com.pousadamarealta.reservas.messaging.ScopedRule.testOnly;
