     7	import java.util.List;
     8	
     9	/**
    10	 * A combinação de regras de e-mail desta instalação, em ordem. É o único lugar a mexer para
    11	 * ligar, desligar ou acrescentar uma regra, e para escolher se vale sempre, só em teste ou só fora dele.
    12	 * <p>
    13	 * Já existem, mas não estão ligadas (faltam os valores combinados com a pousada):
    14	 * {@code always(new QuietHoursRule(clock, LocalTime.of(22, 0), LocalTime.of(8, 0)))} e
    15	 * {@code always(new DailyLimitRule(clock, 5))}; entram antes do redirecionamento de teste.
    16	 */
    17	public final class MessageRules {
    18	
    19	    public static final String TEST_ADDRESS = "testes@pousadamarealta.com.br";
    20	    public static final String ARCHIVE_ADDRESS = "arquivo@pousadamarealta.com.br";
    21	
    22	    private MessageRules() {
    23	    }
    24	
    25	    public static List<ScopedRule> marealta() {
    26	        return List.of(
    27	                always(new ValidAddressRule()),
    28	                testOnly(new TestRedirectRule(TEST_ADDRESS)),
    29	                liveOnly(new ArchiveCopyRule(ARCHIVE_ADDRESS)));
    30	    }
    31	}
