=== messaging/Outbox.java
     1	package br.com.pousadamarealta.reservas.messaging;
     2	
     3	import java.util.ArrayList;
     4	import java.util.List;
     5	
     6	/** Ponto de saída das mensagens: aplica as regras e guarda o resultado na lista de mensagens. */
     7	public final class Outbox {
     8	
     9	    private final MessagePipeline pipeline;
    10	    private final List<Message> messages = new ArrayList<>();
    11	
    12	    public Outbox(MessagePipeline pipeline) {
    13	        this.pipeline = pipeline;
    14	    }
    15	
    16	    public synchronized void send(Channel channel, String to, String subject, String body) {
    17	        Draft draft = new Draft(channel, to, subject, body);
    18	        pipeline.run(draft);
    19	        record(draft, draft.isBlocked() ? MessageStatus.BLOCKED : MessageStatus.SENT);
    20	        draft.copies().forEach(copy -> record(copy, MessageStatus.SENT));
    21	    }
    22	
    23	    public synchronized List<Message> messages() {
    24	        return List.copyOf(messages);
    25	    }
    26	
    27	    private void record(Draft draft, MessageStatus status) {
    28	        messages.add(new Message(messages.size() + 1L, draft.channel(), draft.to(), draft.subject(),
    29	                draft.body(), status));
    30	    }
    31	}
