=== messaging/ValidAddressRule.java
     1	package br.com.pousadamarealta.reservas.messaging;
     2	
     3	/** Bloqueia endereço inválido: um único @, algo antes dele e, depois, um nome com ponto no meio. */
     4	public final class ValidAddressRule implements MessageRule {
     5	
     6	    @Override
     7	    public void apply(Draft draft) {
     8	        if (!isValid(draft.to())) {
     9	            draft.block();
    10	        }
    11	    }
    12	
    13	    static boolean isValid(String address) {
    14	        if (address == null) {
    15	            return false;
    16	        }
    17	        int at = address.indexOf('@');
    18	        if (at <= 0 || at != address.lastIndexOf('@')) {
    19	            return false;
    20	        }
    21	        String domain = address.substring(at + 1);
    22	        return domain.indexOf('.') > 0 && !domain.endsWith(".");
    23	    }
    24	}
