     1	package br.com.pousadamarealta.reservas.web;
     2	
     3	import br.com.pousadamarealta.reservas.domain.DomainException;
     4	import br.com.pousadamarealta.reservas.domain.Reservation;
     5	import br.com.pousadamarealta.reservas.domain.RoomCatalog;
     6	import br.com.pousadamarealta.reservas.messaging.MessagePipeline;
     7	import br.com.pousadamarealta.reservas.messaging.MessageRules;
     8	import br.com.pousadamarealta.reservas.messaging.Outbox;
     9	import br.com.pousadamarealta.reservas.report.OccupancyReport;
    10	import br.com.pousadamarealta.reservas.report.RevenueReport;
    11	import br.com.pousadamarealta.reservas.service.ReservationService;
    12	import com.fasterxml.jackson.databind.ObjectMapper;
    13	import com.fasterxml.jackson.databind.SerializationFeature;
    14	import com.fasterxml.jackson.databind.module.SimpleModule;
    15	import com.fasterxml.jackson.databind.ser.std.ToStringSerializer;
    16	import io.javalin.Javalin;
    17	import io.javalin.http.Context;
    18	import io.javalin.http.Handler;
    19	import io.javalin.json.JavalinJackson;
    20	import java.time.LocalDate;
    21	import java.util.Map;
    22	import java.util.function.LongFunction;
    23	
    24	public final class App {
    25	
    26	    private static final String CSV = "text/csv; charset=utf-8";
    27	
    28	    private final RoomCatalog catalog = RoomCatalog.marealta();
    29	    private final Outbox outbox;
    30	    private final ReservationService reservations;
    31	    private final ObjectMapper mapper = new ObjectMapper()
    32	            .registerModule(new SimpleModule().addSerializer(LocalDate.class, ToStringSerializer.instance))
    33	            .enable(SerializationFeature.WRITE_BIGDECIMAL_AS_PLAIN);
    34	
    35	    private App(Config config) {
    36	        this.outbox = new Outbox(new MessagePipeline(config.testMode(), MessageRules.marealta()));
    37	        this.reservations = new ReservationService(catalog, outbox);
    38	    }
    39	
    40	    public static Javalin create(Config config) {
    41	        return new App(config).javalin();
    42	    }
    43	
    44	    private Javalin javalin() {
    45	        Javalin app = Javalin.create(cfg -> {
    46	            cfg.showJavalinBanner = false;
    47	            cfg.jsonMapper(new JavalinJackson(mapper, false));
    48	        });
    49	        app.exception(DomainException.class, (e, ctx) -> error(ctx, e.code().httpStatus(), e.code().name(), e));
    50	        app.exception(Exception.class, (e, ctx) -> error(ctx, 500, "INTERNAL_ERROR", e));
    51	
    52	        app.get("/rooms", ctx -> ctx.json(catalog.all()));
    53	        app.post("/reservations", ctx -> ctx.status(201).json(ReservationView.of(
    54	                reservations.create(Requests.newReservation(mapper, ctx.body())))));
    55	        app.get("/reservations/{id}", ctx -> ctx.json(ReservationView.of(reservations.get(id(ctx)))));
    56	        app.post("/reservations/{id}/confirmation", reservationAction(reservations::confirm));
    57	        app.post("/reservations/{id}/cancellation", reservationAction(reservations::cancel));
    58	        app.post("/reservations/{id}/check-in", reservationAction(reservations::checkIn));
    59	        app.post("/reservations/{id}/check-out", ctx -> ctx.json(reservations.checkOut(id(ctx))));
    60	        app.get("/reservations/{id}/document", ctx -> ctx.json(reservations.document(id(ctx))));
    61	        app.get("/messages", ctx -> ctx.json(outbox.messages()));
    62	        app.get("/reports/occupancy", ctx -> ctx.contentType(CSV).result(OccupancyReport.render(
    63	                reservations.all(), catalog, Requests.date(ctx.queryParam("date"), "date"))));
    64	        app.get("/reports/revenue", ctx -> ctx.contentType(CSV).result(RevenueReport.render(
    65	                reservations.all(), Requests.month(ctx.queryParam("month")))));
    66	        return app;
    67	    }
    68	
    69	    private Handler reservationAction(LongFunction<Reservation> action) {
    70	        return ctx -> ctx.json(ReservationView.of(action.apply(id(ctx))));
    71	    }
    72	
    73	    private static long id(Context ctx) {
    74	        try {
    75	            return Long.parseLong(ctx.pathParam("id"));
    76	        } catch (NumberFormatException e) {
    77	            return -1;
    78	        }
    79	    }
    80	
    81	    private static void error(Context ctx, int status, String code, Exception e) {
    82	        ctx.status(status).json(Map.of("error", code, "message", String.valueOf(e.getMessage())));
    83	    }
    84	}

