     3	import java.time.Clock;
     4	import java.time.LocalTime;
     5	
     6	/** Bloqueia mensagens no intervalo de silêncio [from, until), que pode atravessar a meia-noite. */
     7	public final class QuietHoursRule implements MessageRule {
     8	
     9	    private final Clock clock;
    10	    private final LocalTime from;
    11	    private final LocalTime until;
    12	
    13	    public QuietHoursRule(Clock clock, LocalTime from, LocalTime until) {
    14	        this.clock = clock;
    15	        this.from = from;
    16	        this.until = until;
    17	    }
    18	
    19	    @Override
    20	    public void apply(Draft draft) {
    21	        LocalTime now = LocalTime.now(clock);
    22	        boolean quiet = from.isBefore(until)
    23	                ? !now.isBefore(from) && now.isBefore(until)
    24	                : !now.isBefore(from) || now.isBefore(until);
    25	        if (quiet) {
    26	            draft.block();
    27	        }
    28	    }
    29	}
