    13	    static boolean isValid(String address) {
    14	        if (address == null) {
    15	            return false;
    16	        }
    17	        int at = address.indexOf('@');
    18	        if (at <= 0 || at != address.lastIndexOf('@')) {
    19	            return false;
    20	        }
    21	        String domain = address.substring(at + 1);
    22	        return domain.indexOf('.') > 0 && !domain.endsWith(".");
    23	    }
    24	}
