     1	package br.com.pousadamarealta.reservas.domain;
     2	
     3	import java.math.BigDecimal;
     4	import java.time.LocalDate;
     5	import java.time.Month;
     6	
     7	public final class Pricing {
     8	
     9	    private static final BigDecimal HIGH_SEASON_FACTOR = new BigDecimal("1.20");
    10	
    11	    private Pricing() {
    12	    }
    13	
    14	    public static Quote quote(Room room, LocalDate checkIn, LocalDate checkOut, RatePlan plan) {
    15	        BigDecimal subtotal = Money.ZERO;
    16	        int nights = 0;
    17	        for (LocalDate night = checkIn; night.isBefore(checkOut); night = night.plusDays(1)) {
    18	            subtotal = subtotal.add(nightPrice(room, night));
    19	            nights++;
    20	        }
    21	        BigDecimal discount = plan.discount(subtotal);
    22	        return new Quote(nights, subtotal, discount, subtotal.subtract(discount));
    23	    }
    24	
    25	    static BigDecimal nightPrice(Room room, LocalDate night) {
    26	        if (isHighSeason(night)) {
    27	            return Money.round(room.nightlyRate().multiply(HIGH_SEASON_FACTOR));
    28	        }
    29	        return room.nightlyRate();
    30	    }
    31	
    32	    /** De 15 de dezembro ao fim de fevereiro, e julho inteiro. */
    33	    static boolean isHighSeason(LocalDate night) {
    34	        Month month = night.getMonth();
    35	        return month == Month.JULY
    36	                || month == Month.JANUARY
    37	                || month == Month.FEBRUARY
