    13	
    14	/** Casos de uso das reservas. Os dados ficam só na memória. */
    15	public final class ReservationService {
    16	
    17	    private final RoomCatalog catalog;
    18	    private final Outbox outbox;
    19	    private final List<Reservation> reservations = new ArrayList<>();
    20	
    21	    public ReservationService(RoomCatalog catalog, Outbox outbox) {
    22	        this.catalog = catalog;
    23	        this.outbox = outbox;
    24	    }
    25	
    26	    public synchronized Reservation create(NewReservation request) {
    27	        if (request.guests() < 1) {
    28	            throw new DomainException(ErrorCode.INVALID_REQUEST, "é preciso ao menos um hóspede");
    29	        }
    30	        if (!request.checkOut().isAfter(request.checkIn())) {
    31	            throw new DomainException(ErrorCode.INVALID_REQUEST, "a saída deve ser depois da entrada");
    32	        }
    33	        Room room = catalog.find(request.roomNumber()).orElseThrow(() ->
    34	                new DomainException(ErrorCode.ROOM_NOT_FOUND, "quarto " + request.roomNumber() + " não existe"));
    35	        if (request.guests() > room.capacity()) {
    36	            throw new DomainException(ErrorCode.CAPACITY_EXCEEDED,
    37	                    "o quarto " + room.number() + " comporta até " + room.capacity() + " pessoas");
    38	        }
    39	        boolean taken = reservations.stream().anyMatch(other -> other.isActive()
    40	                && other.room().number() == room.number()
    41	                && other.overlaps(request.checkIn(), request.checkOut()));
    42	        if (taken) {
    43	            throw new DomainException(ErrorCode.ROOM_UNAVAILABLE,
    44	                    "o quarto " + room.number() + " já está reservado em alguma das noites");
    45	        }
    46	        Reservation reservation = new Reservation(reservations.size() + 1L, room, request.guestName(),
    47	                request.guestEmail(), request.guestCpf(), request.checkIn(), request.checkOut(),
    48	                request.guests(), request.ratePlan());
    49	        reservations.add(reservation);
    50	        return reservation;
    51	    }
    52	
    53	    public synchronized Reservation get(long id) {
    54	        return reservations.stream().filter(r -> r.id() == id).findFirst().orElseThrow(() ->
    55	                new DomainException(ErrorCode.RESERVATION_NOT_FOUND, "reserva " + id + " não existe"));
    56	    }
    57	
    58	    public synchronized List<Reservation> all() {
    59	        return List.copyOf(reservations);
    60	    }
    61	
    62	    public synchronized Reservation confirm(long id) {
    63	        return change(id, reservation -> {
    64	            reservation.confirm();
    65	            Receipt receipt = Receipt.of(reservation);
    66	            outbox.send(Channel.EMAIL, reservation.guestEmail(), ConfirmationEmail.SUBJECT,
    67	                    ConfirmationEmail.body(reservation.guestName(), receipt));
    68	        });
    69	    }
    70	
    71	    public synchronized Reservation cancel(long id) {
    72	        return change(id, Reservation::cancel);
    73	    }
    74	
    75	    public synchronized Reservation checkIn(long id) {
    76	        return change(id, Reservation::registerCheckIn);
    77	    }
    78	
    79	    public synchronized Receipt checkOut(long id) {
    80	        return Receipt.of(change(id, Reservation::registerCheckOut));
    81	    }
    82	
    83	    public synchronized Receipt document(long id) {
    84	        Reservation reservation = get(id);
    85	        reservation.requirePaid();
    86	        return Receipt.of(reservation);
    87	    }
    88	
    89	    private Reservation change(long id, Consumer<Reservation> action) {
    90	        Reservation reservation = get(id);
    91	        action.accept(reservation);
    92	        return reservation;
    93	    }
    94	}
