    26	    public synchronized Reservation create(NewReservation request) {
    27	        if (request.guests() < 1) {
    28	            throw new DomainException(ErrorCode.INVALID_REQUEST, "é preciso ao menos um hóspede");
    29	        }
    30	        if (!request.checkOut().isAfter(request.checkIn())) {
    31	            throw new DomainException(ErrorCode.INVALID_REQUEST, "a saída deve ser depois da entrada");
    32	        }
    33	        Room room = catalog.find(request.roomNumber()).orElseThrow(() ->
    34	                new DomainException(ErrorCode.ROOM_NOT_FOUND, "quarto " + request.roomNumber() + " não existe"));
    35	        if (request.guests() > room.capacity()) {
    36	            throw new DomainException(ErrorCode.CAPACITY_EXCEEDED,
    37	                    "o quarto " + room.number() + " comporta até " + room.capacity() + " pessoas");
    38	        }
    39	        boolean taken = reservations.stream().anyMatch(other -> other.isActive()
    40	                && other.room().number() == room.number()
    41	                && other.overlaps(request.checkIn(), request.checkOut()));
    42	        if (taken) {
    43	            throw new DomainException(ErrorCode.ROOM_UNAVAILABLE,
    44	                    "o quarto " + room.number() + " já está reservado em alguma das noites");
    45	        }
    46	        Reservation reservation = new Reservation(reservations.size() + 1L, room, request.guestName(),
    47	                request.guestEmail(), request.guestCpf(), request.checkIn(), request.checkOut(),
    48	                request.guests(), request.ratePlan());
    49	        reservations.add(reservation);
    50	        return reservation;
    51	    }
